CREATE TABLE "courses" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME "courses_id_seq") NOT NULL,
  CONSTRAINT "courses_pkey" PRIMARY KEY ("id")
);
CREATE TABLE "learners" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME "learners_id_seq") NOT NULL,
  "name" character varying NOT NULL DEFAULT '',
  CONSTRAINT "learners_pkey" PRIMARY KEY ("id")
);
CREATE TABLE "enrollments" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME "enrollments_id_seq") NOT NULL,
  "role" character varying NOT NULL DEFAULT 'member',
  "joined_at" timestamp with time zone NOT NULL,
  "learner_id" bigint NOT NULL DEFAULT 0,
  "course_id" bigint NOT NULL DEFAULT 0,
  CONSTRAINT "enrollments_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "enrollments_courses_course" FOREIGN KEY ("course_id") REFERENCES "courses" ("id"),
  CONSTRAINT "enrollments_learners_learner" FOREIGN KEY ("learner_id") REFERENCES "learners" ("id")
);
CREATE UNIQUE INDEX "enrollments_enrollment_learner_id_course_id" ON "enrollments" ("learner_id", "course_id");
